mapper.select:
SELECT g.id as goods_id, g.goods_name, g.category, g.metal_type, g.store_id, g.sort, g.create_time, (SELECT COUNT(*) FROM mall_goods_spec s WHERE s.goods_id = g.id) as spec_count, (SELECT COALESCE(SUM(s.stock), 0) FROM mall_goods_spec s WHERE s.goods_id = g.id) as total_stock FROM mall_goods g
AND g.category = #{dto.category}
AND g.metal_type = #{dto.metalType}
ORDER BY g.sort ASC, g.create_time DESC
